function tfcBuildDay2Panel(params) {
  // Async (CMP registers it with isAsync): fetch this deployment's variables
  // panel from the form-options webhook and install it as the template of the
  // empty action-input.parameters Dynamic Panel, then resolve so the form's
  // bootstrap question turns from empty into "ready" (or "error: ...").
  var survey = this.survey;
  var done = this.returnResult.bind(this);
  if (!survey) { done("error: no survey instance is available to the form function."); return; }
  var panel = survey.getQuestionByName("action-input.parameters");
  if (!panel) { done("error: this form has no action-input.parameters panel."); return; }
  if (panel.templateElements && panel.templateElements.length > 0) { done("ready"); return; }

  function build(objectId) {
    var id = encodeURIComponent(objectId);
    var url = "/api/v3/cmp/inboundWebHooks/form-options/run/?source=day2_panel&resource=" + id + "&object_id=" + id;
    fetch(url, { credentials: "same-origin", headers: { "Accept": "application/json" } })
      .then(function (response) {
        return response.text().then(function (text) {
          var body = null;
          try { body = JSON.parse(text); } catch (e) { body = { error: "non-JSON reply (HTTP " + response.status + "): " + text.slice(0, 300) }; }
          return { ok: response.ok, status: response.status, body: body };
        });
      })
      .then(function (result) {
        var spec = result.body && result.body.panel;
        if (!result.ok || !spec) {
          done("error: " + ((result.body && result.body.error) || ("HTTP " + result.status)));
          return;
        }
        panel.fromJSON({ templateElements: spec.elements });
        if (spec.title) { panel.title = spec.title; }
        if (spec.description) { panel.description = spec.description; }
        panel.minPanelCount = 1;
        panel.panelCount = 1;
        done("ready");
      })
      .catch(function (error) { done("error: " + error); });
  }

  // CMP injects the object_id question at render time; if this expression ran
  // before its value was set, wait for it rather than depending on
  // re-evaluation order.
  var objectId = params[0];
  var attempts = 0;
  function start() {
    objectId = objectId || survey.getValue("object_id");
    if (objectId) { build(objectId); return; }
    if (attempts++ < 40) { setTimeout(start, 250); return; }
    done("error: the form did not receive the resource id (object_id).");
  }
  start();
}
